// Official public perimeter snapshots frozen for offline diagnostic evaluation.
// Geometry is decoded from the hashed ArcGIS REST responses listed per case.
import { gunzipSync } from 'node:zlib';

function decodeGeometry(chunks) {
  const geometry = JSON.parse(gunzipSync(Buffer.from(chunks.join(''), 'base64')).toString('utf8'));
  // ArcGIS polygon responses can contain multiple same-winding outer rings.
  // GeoJSON treats every ring after the first as a hole, so preserve those
  // disjoint burned areas as a MultiPolygon for the shared rasterizer.
  if (geometry?.type === 'Polygon' && geometry.coordinates.length > 1) {
    const signedArea = (ring) => ring.reduce((total, point, index) => {
      const previous = ring[(index + ring.length - 1) % ring.length];
      return total + previous[0] * point[1] - point[0] * previous[1];
    }, 0);
    const winding = Math.sign(signedArea(geometry.coordinates[0]));
    if (winding !== 0 && geometry.coordinates.slice(1).every((ring) => (
      Math.sign(signedArea(ring)) === winding
    ))) {
      return {
        type: 'MultiPolygon',
        coordinates: geometry.coordinates.map((ring) => [ring])
      };
    }
  }
  return geometry;
}

